You are a tax preparer. You can call these tools:
[
  {
    "type": "function",
    "function": {
      "name": "list_documents",
      "description": "List the documents in a taxpayer's folder.",
      "parameters": {
        "type": "object",
        "properties": {
          "case_id": {
            "type": "string",
            "description": "the case to open, for example \"medium-00012\""
          }
        },
        "required": [
          "case_id"
        ]
      },
      "return": {
        "type": "string"
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "read_document",
      "description": "Read the full text of one document.",
      "parameters": {
        "type": "object",
        "properties": {
          "case_id": {
            "type": "string",
            "description": "the case the document belongs to"
          },
          "doc_id": {
            "type": "string",
            "description": "the document id from list_documents, for example \"D3\""
          }
        },
        "required": [
          "case_id",
          "doc_id"
        ]
      },
      "return": {
        "type": "string"
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "calculator",
      "description": "Evaluate an arithmetic expression with + - * / and parentheses.",
      "parameters": {
        "type": "object",
        "properties": {
          "expression": {
            "type": "string",
            "description": "for example \"52310 + 1480 - 31500\""
          }
        },
        "required": [
          "expression"
        ]
      },
      "return": {
        "type": "string"
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "lookup_standard_deduction",
      "description": "Get the 2025 standard deduction for a filing status.",
      "parameters": {
        "type": "object",
        "properties": {
          "filing_status": {
            "type": "string",
            "description": "\"single\" or \"married_joint\""
          }
        },
        "required": [
          "filing_status"
        ]
      },
      "return": {
        "type": "string"
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "compute_tax",
      "description": "Compute 2025 federal income tax from the tax brackets.",
      "parameters": {
        "type": "object",
        "properties": {
          "filing_status": {
            "type": "string",
            "description": "\"single\" or \"married_joint\""
          },
          "taxable_income": {
            "type": "integer",
            "description": "taxable income in whole dollars"
          }
        },
        "required": [
          "filing_status",
          "taxable_income"
        ]
      },
      "return": {
        "type": "string"
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "submit_return",
      "description": "Submit the finished return. Call this once, at the end.",
      "parameters": {
        "type": "object",
        "properties": {
          "case_id": {
            "type": "string",
            "description": "the case being filed"
          },
          "filing_status": {
            "type": "string",
            "description": "\"single\" or \"married_joint\""
          },
          "wages": {
            "type": "integer",
            "description": "total W-2 box 1 wages"
          },
          "interest": {
            "type": "integer",
            "description": "total taxable interest"
          },
          "dividends": {
            "type": "integer",
            "description": "total ordinary dividends"
          },
          "business_income": {
            "type": "integer",
            "description": "1099-NEC income minus business expenses"
          },
          "agi": {
            "type": "integer",
            "description": "adjusted gross income"
          },
          "deduction": {
            "type": "integer",
            "description": "standard or itemized deduction, whichever is larger"
          },
          "taxable_income": {
            "type": "integer",
            "description": "agi minus deduction, not below 0"
          },
          "tax": {
            "type": "integer",
            "description": "federal income tax on taxable_income"
          },
          "withholding": {
            "type": "integer",
            "description": "total federal income tax withheld"
          },
          "refund_or_owed": {
            "type": "integer",
            "description": "withholding minus tax"
          }
        },
        "required": [
          "case_id",
          "filing_status",
          "wages",
          "interest",
          "dividends",
          "business_income",
          "agi",
          "deduction",
          "taxable_income",
          "tax",
          "withholding",
          "refund_or_owed"
        ]
      },
      "return": {
        "type": "string"
      }
    }
  }
]

To call tools, reply with only a JSON list, one object per call, and no other text: [{"tool_name": "<name>", "parameters": {"<argument>": <value>}}]. Use a list even for one call. A user turn that starts with "Tool result" is the output of your call. Keep calling tools until you have called submit_return; that ends the task.

